function validate([n, highways, k]) {
  if (!Number.isInteger(n) || n < 2 || n > 15) return 'n is between 2 and 15.';
  if (!Array.isArray(highways) || highways.length < 1 || highways.length > 50) return 'highways needs 1 to 50 entries.';
  const seen = new Set();
  for (const h of highways) {
    if (!Array.isArray(h) || h.length !== 3 || !h.every(Number.isInteger)) return 'Each highway is [city1, city2, toll].';
    const [a, b, toll] = h;
    if (a < 0 || a >= n || b < 0 || b >= n) return 'Cities are numbered 0 to n - 1.';
    if (a === b) return 'A highway joins two different cities.';
    if (toll < 0 || toll > 100) return 'Each toll is between 0 and 100.';
    const key = Math.min(a, b) * 16 + Math.max(a, b);
    if (seen.has(key)) return 'Two highways join the same pair of cities.';
    seen.add(key);
  }
  if (!Number.isInteger(k) || k < 1 || k > 50) return 'k is between 1 and 50.';
  return null;
}

