function maximumCost(n, highways, k) {
  if (k >= n) {
    return -1;
  }
  const adj = Array.from({ length: n }, () => []);
  for (const [a, b, toll] of highways) {
    adj[a].push([b, toll]);
    adj[b].push([a, toll]);
  }
  const full = 1 << n;
  const bits = new Array(full).fill(0);
  const dp = Array.from({ length: full }, () => new Array(n).fill(-1));
  for (let city = 0; city < n; city++) {
    dp[1 << city][city] = 0;
  }
  let best = -1;
  for (let mask = 1; mask < full; mask++) {
    bits[mask] = bits[mask >> 1] + (mask & 1);
    if (bits[mask] > k + 1) {
      continue;
    }
    for (let city = 0; city < n; city++) {
      const cost = dp[mask][city];
      if (cost < 0) {
        continue;
      }
      if (bits[mask] === k + 1) {
        best = Math.max(best, cost);
        continue;
      }
      for (const [next, toll] of adj[city]) {
        if (mask & (1 << next)) {
          continue;
        }
        const nextMask = mask | (1 << next);
        dp[nextMask][next] = Math.max(dp[nextMask][next], cost + toll);
      }
    }
  }
  return best;
}

