function maximumCost(n, highways, k) {
  let best = -1;
  const used = new Array(n).fill(false);
  const go = (city, left, total) => {
    if (left === 0) {
      best = Math.max(best, total);
      return;
    }
    for (const [a, b, t] of highways) {
      const other = a === city ? b : b === city ? a : -1;
      if (other < 0 || used[other]) continue;
      used[other] = true;
      go(other, left - 1, total + t);
      used[other] = false;
    }
  };
  for (let start = 0; start < n; start++) {
    used[start] = true;
    go(start, k, 0);
    used[start] = false;
  }
  return best;
}

