function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const large = size === 'large';
  const n = large ? int(12, 15) : int(2, 7);
  const pairs = [];
  for (let a = 0; a < n; a++) for (let b = a + 1; b < n; b++) pairs.push([a, b]);
  for (let i = pairs.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [pairs[i], pairs[j]] = [pairs[j], pairs[i]];
  }
  const m = large ? Math.min(50, pairs.length) : int(1, Math.min(10, pairs.length));
  const maxToll = rand() < 0.2 ? 3 : 100;
  const highways = pairs.slice(0, m).map(([a, b]) => rand() < 0.5 ? [a, b, int(0, maxToll)] : [b, a, int(0, maxToll)]);
  const k = large ? (rand() < 0.1 ? int(n, 50) : int(Math.max(1, n - 6), n - 1)) : int(1, n + 1);
  return [n, highways, k];
}
